const fetch = require('node-fetch');
const GEMINI_API_KEY = process.env.GEMINI_API_KEY;
// ✅ FIXED: Use v1 API with correct model name
const GEMINI_API_URL = 'https://generativelanguage.googleapis.com/v1/models/gemini-1.5-flash:generateContent';
const MATCH_THRESHOLD = 65; 

const enhancedPrompt = (item1, item2) => `
You are a HIGHLY STRICT expert AI system for Lost & Found item matching. Your task is to determine if two items ARE THE EXACT SAME PHYSICAL OBJECT.

Item 1:
Name: ${item1.itemName}
Description: ${item1.description || 'N/A'}
Location: ${item1.locationShort || 'N/A'}
Date: ${item1.date}
Type: ${item1.type}

Item 2:
Name: ${item2.itemName}
Description: ${item2.description || 'N/A'}
Location: ${item2.locationShort || 'N/A'}
Date: ${item2.date}
Type: ${item2.type}

Analyze the items for consistency across categories (e.g., electronic device vs. fruit) and similarity in description, brand, color, location proximity, and time proximity.
If categories differ (e.g., Phone vs. Apple Fruit), score must be 0-5.
If location distance is over 50km, score must be lowered severely (max 20).

Respond ONLY with JSON (NO OTHER TEXT):
{
  "step1_category1": "<category>",
  "step1_category2": "<category>",
  "step2_sameCategory": <true/false>,
  "score": <0-100>,
  "reasoning": "<explanation>"
}
`;

const callGeminiAPI = async (prompt) => {
  if (!GEMINI_API_KEY) {
     console.error("❌ GEMINI API KEY MISSING! Cannot run external AI matching.");
     return { score: 0, reasoning: 'API Key Missing on Server.' };
  }

  const MAX_RETRIES = 3;
  let lastError = null;

  for (let i = 0; i < MAX_RETRIES; i++) {
    try {
        const response = await fetch(`${GEMINI_API_URL}?key=${GEMINI_API_KEY}`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            contents: [{ parts: [{ text: prompt }] }],
            generationConfig: { temperature: 0.4, maxOutputTokens: 1024 }
          })
        });

        if (!response.ok) {
            console.error(`❌ GEMINI API HTTP Error: ${response.status}`);
            const errorData = await response.json().catch(() => ({ message: response.statusText }));
            console.error('Gemini Error Details:', errorData);
            throw new Error(`Gemini API HTTP Error: ${response.status}`);
        }

        const data = await response.json();
        const resultText = data.candidates?.[0]?.content?.parts?.[0]?.text;

        if (!resultText) throw new Error("No text content in Gemini response.");

        const jsonMatch = resultText.match(/\{[\s\S]*\}/);
        if (jsonMatch) {
          const result = JSON.parse(jsonMatch[0]);
          if (!result.step2_sameCategory && result.score > 5) {
             result.score = 5; 
          }
          return result;
        }

        return { score: 40, reasoning: 'Gemini responded, but output JSON parse failed.' };

    } catch (error) {
        lastError = error;
        if (i < MAX_RETRIES - 1) {
            const delay = Math.pow(2, i) * 1000;
            await new Promise(resolve => setTimeout(resolve, delay));
        }
    }
  }

  console.error('Server-side Gemini Error:', lastError);
  return { score: 30, reasoning: `API call failed after retries: ${lastError.message}` };
};

const calculateDistance = (lat1, lon1, lat2, lon2) => {
    const R = 6371; // Earth's radius in km
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLon = (lon2 - lon1) * Math.PI / 180;
    const a = 
        Math.sin(dLat/2) * Math.sin(dLat/2) +
        Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
        Math.sin(dLon/2) * Math.sin(dLon/2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
    return R * c;
};

const calculateLocationTimeScore = (item1, item2) => {
    let locationScore = 0;
    if (item1.actualLocation?.latitude && item2.actualLocation?.latitude) {
        const distance = calculateDistance(
            item1.actualLocation.latitude, item1.actualLocation.longitude,
            item2.actualLocation.latitude, item2.actualLocation.longitude
        );

        if (distance <= 0.5) locationScore = 100;
        else if (distance <= 5) locationScore = 85;
        else if (distance <= 20) locationScore = 60;
        else if (distance <= 50) locationScore = 30;
        else locationScore = 10;

        console.log(`[GeoTime] Distance: ${distance.toFixed(2)}km, Score: ${locationScore.toFixed(1)}%`);

    } else {
        locationScore = 40; 
    }

    let timeScore = 0;
    try {
        const datetime1 = new Date(`${item1.date}T${item1.time || '12:00:00'}`).getTime();
        const datetime2 = new Date(`${item2.date}T${item2.time || '12:00:00'}`).getTime();
        const hoursDiff = Math.abs(datetime1 - datetime2) / (1000 * 60 * 60);

        if (hoursDiff <= 12) timeScore = 100;
        else if (hoursDiff <= 48) timeScore = 90;
        else if (hoursDiff <= 168) timeScore = 70;
        else if (hoursDiff <= 720) timeScore = 40;
        else timeScore = 15;

        console.log(`[GeoTime] Time Diff: ${hoursDiff.toFixed(1)}h, Score: ${timeScore.toFixed(1)}%`);

    } catch (e) {
        timeScore = 50;
    }


    return (locationScore * 0.6 + timeScore * 0.4);
};

const calculateMatchScore = async (item1, item2) => {
    // 1. Gemini AI check (for semantic, category, brand match)
    const geminiResult = await callGeminiAPI(enhancedPrompt(item1, item2));

    let aiScore = geminiResult.score || 0;

    if (geminiResult.step2_sameCategory === false) {
         console.log(`[AI Match] Category Mismatch Detected: ${geminiResult.step1_category1} vs ${geminiResult.step1_category2}. Score forced to 0.`);
         return 0; 
    }

    if (aiScore === 0) {
        console.log(`[AI Match] Gemini score is 0, skipping Geo/Time check.`);
        return 0; 
    }

    // 2. Location and Time Check (objective factors)
    const geoTimeScore = calculateLocationTimeScore(item1, item2);

    // 3. Final Weighted Score (60% AI, 40% Geo/Time)
    const finalScore = (aiScore * 0.6) + (geoTimeScore * 0.4);

    console.log(`[AI Match] Final Score Breakdown: AI=${aiScore.toFixed(1)}%, GeoTime=${geoTimeScore.toFixed(1)}%, FINAL=${finalScore.toFixed(1)}%`);

    return Math.round(Math.min(100, Math.max(0, finalScore)));
};

module.exports = { calculateMatchScore, MATCH_THRESHOLD };
